"""Rebuild this lesson's pages from content.js exported as JSON. No student records are touched."""
from pathlib import Path
import json, html, sys
ROOT=Path(__file__).resolve().parents[2]
DEST=ROOT/'du/textbook/2hcl/unit1/ba-ai-shuo-chu-lai'
L=json.loads(Path(sys.argv[1]).read_text())
S='../../../shared/lesson-v1/'
E=html.escape
VERSION=L['version']
def shell(title,body,scripts='',nav=''):
    return f'''<!doctype html><html lang="zh-SG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="中二高级华文 单元一 把爱说出来 课文教学配套"><title>{title} · 华文通</title><link rel="stylesheet" href="{S}style.css?v={VERSION}"></head><body><header class="site-header"><a href="../../../../../index.html"><img src="../../../../../assets/huawentong-logo.png" alt="华文通"></a><span>中二高级华文 · 单元一</span></header>{nav}<main>{body}</main>{scripts}</body></html>'''
def out(name,body): (DEST/name).write_text(body)
def panel(n):
    x,y,w,h=L['panelRects'][n-1]
    return f'<div class="panel" style="aspect-ratio:{w}/{h}"><img src="assets/comic{(n-1)//10+1}.png" alt="原有漫画第{n}格" style="width:{1024/w*100}%;left:{-x/w*100}%;top:{-y/h*100}%"></div>'
nav='<nav class="nav"><a class="btn" href="index.html">Home（主页）</a><button data-view="read">Read（读文）</button><button data-view="lesson1">Lesson 1（第一课）</button><button data-view="lesson2">Lesson 2（第二课）</button><button data-view="lesson3">Lesson 3（第三课）</button><button data-view="review">Review（检查）</button><button id="wordList">My words（词语本）</button></nav>'
reading='''<p id="saveState" class="muted" role="status"></p><div id="readTask" class="workspace"><article id="source" class="paper"></article><section id="activity" class="paper"></section></div><section id="review" class="paper" hidden></section><dialog id="dialog"><button id="dialogClose" class="dialog-close">Close（关闭）</button><div id="dialogContent"></div></dialog><dialog id="wordDialog"><button id="wordDialogClose" class="dialog-close">Close（关闭）</button><div id="wordDialogContent"></div></dialog>'''
scripts=f'<script src="content.js?v={VERSION}"></script><script src="lexicon.js?v={VERSION}"></script><script src="{S}wordbook.js?v={VERSION}"></script><script src="{S}app.js?v={VERSION}"></script>'
out('reading.html',shell('把爱说出来 · 互动学习',reading,scripts,nav))
out('index.html',shell('把爱说出来',f'''<p class="crumb"><a href="../../../../../index.html">华文通</a> / 中二 / 课文学习 / 单元一</p><section class="hero"><div><p class="eyebrow">CORE TEXT · 核心课文</p><h1>把爱说出来</h1><p class="lead">有爱在心，为什么难以开口？</p><p>Compare people（比较人物）<br>Read feelings through evidence（以证据读懂心情）</p><div class="actions"><a class="btn primary" href="reading.html">Start / continue（开始／继续）</a><a class="btn" href="reading.html#words">My words（词语本）</a></div></div><div>{panel(27)}</div></section><section class="cards"><article class="card"><h2>Lesson 1</h2><h3>谁怎样表达爱？</h3><p>Read paragraphs 1–11.<br>Compare words and actions.</p><a href="reading.html#lesson1">Tasks 1–4（人物与感受）</a></article><article class="card"><h2>Lesson 2</h2><h3>“我”为什么犹豫？</h3><p>Read paragraphs 12–15.<br>Use evidence to explain.</p><a href="reading.html#lesson2">Tasks 5–7（心理与比较）</a></article><article class="card"><h2>Lesson 3</h2><h3>歌声告诉我们什么？</h3><p>Read paragraph 16.<br>Explain and respond.</p><a href="reading.html#lesson3">Tasks 8–10（结尾与回应）</a></article></section><div class="actions"><a class="btn" href="../../../..//ciyu/context-lab/index.html?unit=1#s2u1l2">Word practice（词语预习）</a><a class="btn" href="comics.html">Reread（漫画回读）</a><a class="btn" href="reading.html#review">My record（学习记录）</a></div><div class="teacher-link"><a href="teacher.html">Teacher resources（教师资料）</a></div>'''.replace('../../../..//ciyu','../../../../ciyu')))
out('comics.html',shell('把爱说出来 · 漫画回读',f'''<p class="crumb"><a href="index.html">Lesson home（课文主页）</a> / Reread（回读）</p><h1>把爱说出来</h1><p>Read by paragraph（逐段读）: <a href="reading.html#read">Open（开始）</a></p>{''.join(f'<img class="comic-full" src="assets/comic{i}.png" alt="把爱说出来 原有漫画第{i}张"><p class="actions"><a class="btn" href="assets/comic{i}.png" download>Download original（下载原图 {i}）</a></p>' for i in range(1,4))}<section class="text-full">{''.join(f'<h3>第{i+1}段</h3><p>{E(p)}</p>' for i,p in enumerate(L['paragraphs']))}<p>{E(L['author'])}</p></section>'''))
teacher='''<p class="crumb"><a href="index.html">课文主页</a> / 教师资料</p><h1>把爱说出来</h1><p>中二高级华文 · 单元一 · 建议3课时，每课50分钟；另附2课时压缩流程。</p><div class="actions"><a class="btn primary" href="slides.html">在线投影</a><a class="btn" href="downloads/ba-ai-shuo-chu-lai.pptx" download>下载可编辑PPT</a><a class="btn" href="downloads/teacher-guide.docx" download>下载教师流程与答案</a><button id="downloadPack">下载整套配套</button></div><p id="packStatus" role="status"></p><div class="actions"><button id="downloadOffline">下载独立互动HTML</button><a class="btn" href="comics.html">漫画与全文</a></div><h2>教学目标</h2><ol>'''+''.join('<li><p>'+E(x)+'</p></li>' for x in L['objectives'])+'''</ol><h2>课堂安排</h2><table><tr><th>课次</th><th>流程</th><th>输入量</th></tr><tr><td>第一课</td><td>短导入；第1–11段图文阅读；任务1–4；词语整理。</td><td>任务3简答，其余点选、取证与口头追问。</td></tr><tr><td>第二课</td><td>第12–15段；任务5–7；自主人物比较与订正。</td><td>任务5原因短答、任务7人物比较。</td></tr><tr><td>第三课</td><td>第16段；任务8–10；结尾、观点讨论、必做开放回应。</td><td>任务9简记、任务10开放回应。</td></tr></table><p>两课时版：第一课完成第1–11段及任务1–4。第二课完成第12–16段与任务5–10，其中任务5、9由教师投影组织口头共构，独立书面保留任务7与10。减少重复汇报，不把共构结果当成独立掌握证据。若只有两个40分钟课时，建议采用三课时安排。</p><h2>文本边界</h2><p>儿子拒绝听文章、否定妹妹的赞美是明示信息；他的内心感情只能谨慎推断。结尾歌声支持母亲感到爱与安慰、心情有所好转，不证明她从此永不悲伤。课本把女儿“双眼含笑、一脸欣赏”等列为外貌描写，细分可称神态。</p><h2>参考答案</h2>'''
for i,t in enumerate(L['tasks']):
    teacher+=f'<details><summary>{i+1}. {E(t["title"])} · {E(t["source"])}</summary>'+''.join('<p class="question">'+E(q)+'</p>' for q in t['questions'])+f'<p class="model">{E(t["answer"])}</p><p>{E(t["explain"])}</p><p>易错点：{E(t["reject"])}</p>'+''.join('<p>其他合理方向：'+E(x)+'</p>' for x in t.get('alternatives',[]))+''.join('<p><b>'+E(q)+'</b><br>'+E(a)+'</p>' for q,a in t.get('oral',[]))+'</details>'
teacher+='''<h2>使用与记录</h2><p>教师页含参考答案，为公开资源；课堂请直接发送 reading.html 学生链接。首次回答、订正、提示使用及提交时间保存在当前设备的浏览器；支持逐题CSV、JSON和文字记录导出。没有接入Google Sheet，也不会自动发送教师。</p><p>个人词语本与《团圆饭》沿用同域共享格式。已收录词自动建卡并带入释义、原句；未知词可收藏，标为待补释义。同词保留已有释义与熟悉状态，本课不同语境义另列。清理浏览器会丢失本地记录，重置本课不会删除词语本。共享设备请使用各自浏览器资料或分别备份。直接打开离线HTML可能因浏览器限制无法长期保存，请导出记录。</p><p>中文课文、题答用楷体；指令和解析用清晰宋体。设备朗读依赖浏览器，不是人工录音。没有倒计时、速度分和个人排行榜。</p><p class="footer-note">资源依据：本次上传的16段课文、阅读放大镜、读后说及3页教参。参考答案与建议分值用于课堂讲评，不冒充官方考试评分。漫画沿用用户提供的三张原图。网页版通过脚本与DOM模拟验证；未做真实iPad实测。</p>'''
out('teacher.html',shell('把爱说出来 · 教师资料',teacher,'<script src="pack.js"></script>'))
slides=json.loads((DEST/'slides.json').read_text()) if (DEST/'slides.json').exists() else []
if slides:
    notes=json.dumps(slides,ensure_ascii=False)
    out('slides.html',shell('把爱说出来 · 在线投影','''<p class="crumb"><a href="teacher.html">教师资料</a> / 在线投影</p><div class="toolbar"><a class="btn" href="#1">第一课</a><a class="btn" href="#18">第二课</a><a class="btn" href="#31">第三课</a><select id="slideSelect" aria-label="选择课件页"></select></div><section class="projector" id="projector"><img id="slideImage" alt="课件"><div class="toolbar"><button id="prev">Previous（上一页）</button><button id="next">Next（下一页）</button><button id="full">Full screen（全屏）</button><span class="slide-label" id="slideLabel"></span></div></section><details class="slide-notes"><summary>Teacher notes（教师提示）</summary><p id="notes"></p></details>''',f'''<script>const SLIDES={notes};const $=s=>document.querySelector(s);let n=1;$('#slideSelect').innerHTML=SLIDES.map((s,i)=>`<option value="${{i+1}}">${{i+1}}. ${{s.title}}</option>`).join('');function show(){{n=Math.max(1,Math.min(SLIDES.length,parseInt(location.hash.slice(1))||1));$('#slideImage').src='slides/slide-'+String(n).padStart(2,'0')+'.png';$('#slideImage').alt=SLIDES[n-1].title;$('#slideLabel').textContent=n+' / '+SLIDES.length;$('#notes').textContent=SLIDES[n-1].notes;$('#slideSelect').value=n;$('#prev').disabled=n===1;$('#next').disabled=n===SLIDES.length;}}$('#prev').onclick=()=>location.hash=n-1;$('#next').onclick=()=>location.hash=n+1;$('#slideSelect').onchange=e=>location.hash=e.target.value;$('#full').onclick=()=>$('#projector').requestFullscreen?.();window.onhashchange=show;window.onkeydown=e=>{{if(e.target.tagName==='SELECT')return;if(e.key==='ArrowRight'&&n<SLIDES.length)location.hash=n+1;if(e.key==='ArrowLeft'&&n>1)location.hash=n-1;}};show();</script>'''))
print('Pages rebuilt', DEST)
